    "abstraction": {
      "state_properties": {
        "has_cart": "hasCart",
        "no_cart": {
          "not": "has_cart"
        },
        "carrying_by_hand": "handFull"
      },
      "events": {
        "barehand_pickup": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "no_cart"
